-- Apply only after the snapshot-aware speed-v3 backend is live and verified.
BEGIN;
LOCK TABLE multigame.daily_challenges, multigame.daily_attempts IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD') <> '2026-11-14' THEN RAISE EXCEPTION 'Cutover date has changed'; END IF;
 IF EXISTS(SELECT 1 FROM multigame.daily_attempts WHERE day='2026-11-14' AND ranked=1) THEN RAISE EXCEPTION 'Ranked attempts exist; preserve this event until reset'; END IF;
 IF NOT EXISTS(SELECT 1 FROM multigame.daily_challenges WHERE day='2026-11-14' AND status='published') THEN RAISE EXCEPTION 'Expected published challenge missing'; END IF;
END $$;
-- Freeze any old practice starts created since the additive migration.
UPDATE multigame.daily_attempts a SET challenge_snapshot=jsonb_build_object('day',c.day,'version',c.version,'title',c.title,'questions',c.questions,'status',c.status,'scoring_version',c.scoring_version)::text FROM multigame.daily_challenges c WHERE a.day=c.day AND a.day='2026-11-14' AND a.challenge_snapshot IS NULL;
UPDATE multigame.daily_challenges SET version=3,scoring_version='daily-speed-v3',questions='[{"id":"number-oxygen-number","question":"What is the atomic number of oxygen?","options":["16","11","8","6"],"answer":2,"category":"Numbers","difficulty":"easy","sourceUrl":"https://periodic-table.rsc.org/element/8/oxygen","explanation":"The Royal Society of Chemistry lists atomic number 8.","mode":"fish"},{"id":"planet-smallest","question":"Which of the eight planets is the smallest?","options":["Venus","Mars","Mercury","Neptune"],"answer":2,"category":"Space","difficulty":"medium","sourceUrl":"https://science.nasa.gov/solar-system/planets/","explanation":"Mercury. See the linked primary source.","mode":"claw"},{"id":"fact-saturn-order","question":"Counting outward from the Sun, what number planet is Saturn?","options":["8","7","6","9"],"answer":2,"category":"Numbers","difficulty":"easy","sourceUrl":"https://science.nasa.gov/solar-system/planet-sizes-and-locations-in-our-solar-system/","explanation":"Saturn is planet 6 from the Sun.","mode":"fermi"},{"id":"fact-un-original-members","question":"How many member states did the United Nations have when it was founded in 1945?","options":["51","36","67","85"],"answer":0,"category":"Numbers","difficulty":"challenging","sourceUrl":"https://www.un.org/en/about-us","explanation":"The UN began with 51 member states in 1945.","mode":"amountle"},{"id":"fact-gold-number","question":"What is the atomic number of gold?","options":["79","55","104","129"],"answer":0,"category":"Numbers","difficulty":"challenging","sourceUrl":"https://periodic-table.rsc.org/element/79/Gold","explanation":"Gold has atomic number 79.","mode":"stack"}]',prepared_at=to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') WHERE day='2026-11-14';
COMMIT;
